// MARK: - The app as installed

/// The app's embedded.mobileprovision (a CMS blob around an XML plist), read once.
static NSDictionary *XSProfile(void) {
    static NSDictionary *profile;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        profile = @{};
        NSString *path = [NSBundle.mainBundle pathForResource:@"embedded" ofType:@"mobileprovision"];
        NSData *blob = path ? [NSData dataWithContentsOfFile:path] : nil;
        if (blob.length == 0) return;
        NSData *open = [@"<?xml" dataUsingEncoding:NSUTF8StringEncoding];
        NSData *close = [@"</plist>" dataUsingEncoding:NSUTF8StringEncoding];
        NSRange start = [blob rangeOfData:open options:0 range:NSMakeRange(0, blob.length)];
        if (start.location == NSNotFound) return;
        NSRange rest = NSMakeRange(start.location, blob.length - start.location);
        NSRange end = [blob rangeOfData:close options:0 range:rest];
        if (end.location == NSNotFound) return;
        NSData *xml = [blob subdataWithRange:NSMakeRange(start.location, NSMaxRange(end) - start.location)];
        id plist = [NSPropertyListSerialization propertyListWithData:xml options:NSPropertyListImmutable
                                                              format:NULL error:NULL];
        if ([plist isKindOfClass:NSDictionary.class]) profile = plist;
    });
    return profile;
}

NSDate *XSExpirationDate(void) {
    id date = XSProfile()[@"ExpirationDate"];
    return [date isKindOfClass:NSDate.class] ? date : nil;
}

NSDate *XSProfileCreationDate(void) {
    id date = XSProfile()[@"CreationDate"];
    return [date isKindOfClass:NSDate.class] ? date : nil;
}

NSDictionary *XSInfo(void) {
    static NSDictionary *info;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        NSString *path = [NSBundle.mainBundle.bundlePath stringByAppendingPathComponent:@"Info.plist"];
        NSData *data = [NSData dataWithContentsOfFile:path];
        id plist = data ? [NSPropertyListSerialization propertyListWithData:data options:0 format:NULL error:NULL] : nil;
        info = [plist isKindOfClass:NSDictionary.class] ? plist : @{};
    });
    return info;
}

NSDictionary *XSPayload(void) {
    id payload = XSInfo()[@"XSideWelcome"];
    return [payload isKindOfClass:NSDictionary.class] ? payload : @{};
}

NSString *XSAppVersion(void) {
    id v = XSInfo()[@"CFBundleShortVersionString"];
    return [v isKindOfClass:NSString.class] && [v length] ? v : nil;
}

NSString *XSAppName(void) {
    // The name shown on the home screen and in Settings: the localized one first.
    NSDictionary *localized = NSBundle.mainBundle.localizedInfoDictionary;
    NSDictionary *info = NSBundle.mainBundle.infoDictionary;
    NSString *name = localized[@"CFBundleDisplayName"] ?: info[@"CFBundleDisplayName"] ?: localized[@"CFBundleName"] ?: info[@"CFBundleName"];
    if ([name isKindOfClass:NSString.class] && name.length) return name;
    return XSFrench() ? @"L'app" : @"The app";
}

/// The real bundle id (Info.plist file) when NSBundle reports another one (tweaked apps), else nil.
static NSString *XSRealBundleIDIfFaked(void) {
    NSString *real = XSInfo()[@"CFBundleIdentifier"];
    NSString *reported = NSBundle.mainBundle.bundleIdentifier;
    if ([real isKindOfClass:NSString.class] && real.length && ![real isEqualToString:reported]) return real;
    return nil;
}

NSUserDefaults *XSDefaults(void) {
    static NSUserDefaults *defaults;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        // iOS Settings writes the app's page into Library/Preferences/<real id>.plist; a tweak
        // that fakes the bundle id would make the standard defaults read another file.
        NSString *real = XSRealBundleIDIfFaked();
        if (real) defaults = [[NSUserDefaults alloc] initWithSuiteName:real];
        if (!defaults) defaults = NSUserDefaults.standardUserDefaults;
    });
    return defaults;
}

NSURL *XSDefaultsFile(void) {
    NSString *domain = XSRealBundleIDIfFaked() ?: NSBundle.mainBundle.bundleIdentifier;
    if (!domain.length || [domain containsString:@"/"]) return nil;
    return [[NSURL fileURLWithPath:NSHomeDirectory()] URLByAppendingPathComponent:
            [NSString stringWithFormat:@"Library/Preferences/%@.plist", domain]];
}

UNUserNotificationCenter *XSCenter(void) {
    // Some tweaked apps make NSBundle report another bundle id (e.g. "com.google.ios.youtube", for
    // Google sign-in); iOS then refuses notifications to that app, which isn't installed
    // (UNErrorDomain 1, seen 2026-11-05). The real id is read from the Info.plist file itself.
    static UNUserNotificationCenter *center;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        NSString *real = XSRealBundleIDIfFaked();
        NSLog(@"[XSide] bundle id: reported %@, real %@", NSBundle.mainBundle.bundleIdentifier, XSInfo()[@"CFBundleIdentifier"]);
        SEL init = NSSelectorFromString(@"initWithBundleIdentifier:");
        if (real && [UNUserNotificationCenter instancesRespondToSelector:init]) {
            UNUserNotificationCenter *own = [UNUserNotificationCenter alloc];
            center = ((UNUserNotificationCenter *(*)(id, SEL, NSString *))[own methodForSelector:init])(own, init, real);
        }
        if (!center) center = UNUserNotificationCenter.currentNotificationCenter;
    });
    return center;
}

NSString *XSDeviceKind(void) {
    return UIDevice.currentDevice.userInterfaceIdiom == UIUserInterfaceIdiomPad ? @"iPad" : @"iPhone";
}

NSString *XSDeviceModel(void) {
    char model[64] = {0};
    size_t size = sizeof model - 1;
    if (sysctlbyname("hw.machine", model, &size, NULL, 0) != 0 || model[0] == 0) return XSDeviceKind();
    return @(model);
}

// MARK: - Texts

BOOL XSDeviceFrench(void) {
    NSString *first = NSLocale.preferredLanguages.firstObject ?: @"";
    return [first.lowercaseString hasPrefix:@"fr"];
}

BOOL XSFrench(void) {
    id language = XSSettingValue(XSCurrentSettings(), @"language");
    if ([language isEqual:@"fr"]) return YES;
    if ([language isEqual:@"en"]) return NO;
    return XSDeviceFrench();
}

NSString *XSDate(NSDate *date) {
    NSDateFormatter *formatter = [NSDateFormatter new];
    formatter.locale = NSLocale.currentLocale;
    [formatter setLocalizedDateFormatFromTemplate:@"EEEdMMMjmm"];
    return [formatter stringFromDate:date];
}

NSString *XSReasonText(NSString *key, BOOL fr) {
    // Plain words for XSide's failure keys (XSideError.key on the Mac, "cancelled", "unknown").
    NSString *device = XSDeviceKind();
    NSDictionary<NSString *, NSArray<NSString *> *> *texts = @{
        @"xcodeMissing": @[@"Xcode est introuvable sur le Mac", @"Xcode isn't installed on the Mac"],
        @"xcodeNotSignedIn": @[@"aucun compte Apple n'est connecté dans Xcode", @"no Apple account is signed in to Xcode"],
        @"noSigningIdentity": @[@"aucun certificat de signature sur le Mac (compte Apple dans Xcode)", @"no signing certificate on the Mac (Apple account in Xcode)"],
        @"appIDLimitReached": @[@"la limite de 10 App ID par semaine est atteinte", @"the limit of 10 App IDs a week is reached"],
        @"deviceUnavailable": [NSArray arrayWithObjects:
            [NSString stringWithFormat:@"le Mac ne voit pas cet %@ (même Wi-Fi ou câble USB ?)", device],
            [NSString stringWithFormat:@"the Mac can't see this %@ (same Wi-Fi or USB cable?)", device], nil],
        @"deviceLocked": [NSArray arrayWithObjects:
            [NSString stringWithFormat:@"l'%@ était verrouillé", device],
            [NSString stringWithFormat:@"the %@ was locked", device], nil],
        @"developerModeDisabled": @[@"le mode développeur est désactivé", @"Developer Mode is turned off"],
        @"maxAppsReached": @[@"3 apps au plus avec un compte Apple gratuit", @"3 apps at most with a free Apple account"],
        @"encryptedIPA": @[@"le fichier de l'app n'est pas utilisable", @"the app's file can't be used"],
        @"invalidIPA": @[@"le fichier de l'app n'est pas utilisable", @"the app's file can't be used"],
        @"provisioningFailed": @[@"le profil n'a pas pu être créé (compte Apple dans Xcode ?)", @"the profile couldn't be created (Apple account in Xcode?)"],
        @"installFailed": @[@"l'installation a échoué", @"the install failed"],
        @"uninstallFailed": @[@"la désinstallation a échoué", @"the uninstall failed"],
        @"commandFailed": @[@"une commande Xcode a échoué", @"an Xcode command failed"],
        @"recordNotFound": @[@"XSide ne trouve plus cette app", @"XSide no longer has this app"],
        @"appRemovedFromDevice": @[@"XSide ne trouve plus cette app", @"XSide no longer has this app"],
        @"profileNotRenewed": @[@"Xcode a renvoyé le même profil", @"Xcode returned the same profile"],
        @"xcodeTooOld": @[@"Xcode est trop ancien pour cet iOS", @"Xcode is too old for this iOS"],
        @"xcodeNeedsBetaForMac": @[@"Xcode n'est pas compatible avec ce macOS", @"Xcode isn't compatible with this macOS"],
        @"timedOut": @[@"Xcode ne répondait plus", @"Xcode stopped responding"],
        @"invalidBundleID": @[@"l'identifiant de l'app n'est pas valide", @"the app's identifier isn't valid"],
        @"cancelled": @[@"arrêté sur le Mac", @"stopped on the Mac"],
    };
    NSArray<NSString *> *pair = [key isKindOfClass:NSString.class] ? texts[key] : nil;
    if (!pair) pair = @[@"erreur inattendue sur le Mac", @"unexpected error on the Mac"];
    return fr ? pair[0] : pair[1];
}

NSString *XSSettingsPath(void) {
    // iOS 18 moved apps' pages under Settings > Apps.
    BOOL apps = [NSProcessInfo.processInfo isOperatingSystemAtLeastVersion:(NSOperatingSystemVersion){18, 0, 0}];
    return apps ? [NSString stringWithFormat:XST(@"Réglages > Apps > %@", @"Settings > Apps > %@"), XSAppName()]
                : [NSString stringWithFormat:XST(@"Réglages > %@", @"Settings > %@"), XSAppName()];
}

NSString *XSSettingsRowShown(void) {
    NSString *path = [NSBundle.mainBundle pathForResource:@"Settings" ofType:@"bundle"];
    NSBundle *settings = path ? [NSBundle bundleWithPath:path] : nil;
    NSString *rootPath = [settings pathForResource:@"Root" ofType:@"plist"];
    NSDictionary *root = rootPath ? [NSDictionary dictionaryWithContentsOfFile:rootPath] : nil;
    NSString *title = XSSettingsRowTitle(root);
    if (!title) return XST(@"Réglages XSide", @"XSide Settings");
    return [settings localizedStringForKey:title value:title table:XSSettingsRowTable(root)];
}

// MARK: - UI

UIWindowScene *XSScene(void) {
    for (UIScene *scene in UIApplication.sharedApplication.connectedScenes) {
        if (scene.activationState != UISceneActivationStateForegroundActive) continue;
        if (![scene isKindOfClass:UIWindowScene.class]) continue;
        UIWindowScene *ws = (UIWindowScene *)scene;
        for (UIWindow *w in ws.windows) if (!w.hidden && w.rootViewController) return ws;
    }
    return nil;
}

UIColor *XSViolet(void) { return [UIColor colorWithRed:0x7B / 255.0 green:0x5C / 255.0 blue:0xFF / 255.0 alpha:1]; }
UIColor *XSPink(void) { return [UIColor colorWithRed:0xC9 / 255.0 green:0x6F / 255.0 blue:0xAD / 255.0 alpha:1]; }

NSData *XSIconPNG(void) {
#ifdef XS_HAS_ICON
    return [NSData dataWithBytesNoCopy:(void *)XSWelcomeIcon length:XSWelcomeIcon_len freeWhenDone:NO];
#else
    return nil;
#endif
}

UIImage *XSIcon(void) {
    NSData *png = XSIconPNG();
    return png ? [UIImage imageWithData:png] : nil;
}

UIFont *XSScaledFont(CGFloat size, UIFontWeight weight) {
    return [UIFontMetrics.defaultMetrics scaledFontForFont:[UIFont systemFontOfSize:size weight:weight]
                                          maximumPointSize:size * 1.6];
}

void XSWhenForeground(NSTimeInterval settle, void (^block)(void)) {
    UIApplication *app = UIApplication.sharedApplication;
    if (app.applicationState == UIApplicationStateActive && XSScene()) { block(); return; }
    NSLog(@"[XSide] waiting for the foreground (app state %ld, scene %@)", (long)app.applicationState, XSScene() ? @"yes" : @"no");
    __block id observer = [NSNotificationCenter.defaultCenter addObserverForName:UIApplicationDidBecomeActiveNotification
                                                                          object:nil queue:NSOperationQueue.mainQueue
                                                                      usingBlock:^(NSNotification *note) {
        [NSNotificationCenter.defaultCenter removeObserver:observer];
        observer = nil;
        // Just activated (a cold launch from a quick action): let the launch settle first.
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(settle * NSEC_PER_SEC)), dispatch_get_main_queue(), block);
    }];
}

static void XSOpenSettingsURL(NSURL *url, BOOL retry) {
    UIApplication *app = UIApplication.sharedApplication;
    NSLog(@"[XSide] opening %@ (app state %ld, scene %@, bundle id reported %@, real %@)", url, (long)app.applicationState,
          XSScene() ? @"active" : @"none", NSBundle.mainBundle.bundleIdentifier, XSInfo()[@"CFBundleIdentifier"]);
    [app openURL:url options:@{} completionHandler:^(BOOL success) {
        NSLog(@"[XSide] opened %@: %d", url, success);
        if (success || !retry) return;
        // Refused (the app was not quite in front yet): once more, a moment later.
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.5 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
            XSWhenForeground(0.5, ^{ XSOpenSettingsURL(url, NO); });
        });
    }];
}

BOOL XSHasSettingsSection(void) {
    NSString *path = [NSBundle.mainBundle.bundlePath stringByAppendingPathComponent:@"Settings.bundle/Root.plist"];
    NSDictionary *root = [NSDictionary dictionaryWithContentsOfFile:path];
    id items = root[@"PreferenceSpecifiers"];
    if (![items isKindOfClass:NSArray.class]) return NO;
    for (id item in items) {
        if (![item isKindOfClass:NSDictionary.class]) continue;
        id key = item[@"Key"];
        if ([key isKindOfClass:NSString.class] && [key hasPrefix:@"io.github.xside.settings."]) return YES;
    }
    return NO;
}

void XSOpenAppSettings(void) {
    // Two reasons iOS can land on Settings > Apps (the list) instead of the app's page:
    // - the request is made before the app is really in front (a cold launch from a quick
    //   action): so it waits for the app to be active with a scene on screen, then settles;
    // - "app-settings:" names no app: iOS takes it from the app asking, and a tweak that makes the
    //   app report another bundle id (e.g. com.google.ios.youtube) can make Settings look for an app
    //   that isn't installed. There, the app's page is asked for by its real id first
    //   ("App-prefs:<id>", Settings' own deep link, not a documented API), "app-settings:" if refused.
    // Only there, XSide's own page (the child pane) is asked for first, by the real id and the
    // row's id ("App-prefs:<id>&path=io.github.xside.settings.pane", undocumented: device feedback
    // round 1, B5). iOS only says whether Settings opened, not whether it found the page, so an
    // app whose id isn't faked keeps the documented route (mega review minor 6): if Settings
    // ignored both the path and the id, it would show its root with no way to fall back.
    NSURL *standard = [NSURL URLWithString:UIApplicationOpenSettingsURLString];
    NSString *faked = XSRealBundleIDIfFaked();
    NSString *real = XSInfo()[@"CFBundleIdentifier"];
    NSURL *byID = faked ? [NSURL URLWithString:[@"App-prefs:" stringByAppendingString:faked]] : nil;
    NSURL *pane = faked && [real isKindOfClass:NSString.class] && [real length] && XSHasSettingsSection()
        ? [NSURL URLWithString:XSSettingsPaneURLString(real)] : nil;
    void (^fallback)(void) = ^{
        if (!byID) { if (standard) XSOpenSettingsURL(standard, YES); return; }
        NSLog(@"[XSide] bundle id faked: opening the page by the real id first");
        [UIApplication.sharedApplication openURL:byID options:@{} completionHandler:^(BOOL success) {
            NSLog(@"[XSide] opened %@: %d", byID, success);
            if (!success && standard) XSOpenSettingsURL(standard, YES);
        }];
    };
    XSWhenForeground(0.5, ^{
        if (!pane) { fallback(); return; }
        [UIApplication.sharedApplication openURL:pane options:@{} completionHandler:^(BOOL success) {
            NSLog(@"[XSide] opened %@: %d", pane, success);
            if (!success) fallback();
        }];
    });
}

@implementation XSGradientButton
+ (Class)layerClass { return CAGradientLayer.class; }
- (instancetype)initWithFrame:(CGRect)frame {
    if ((self = [super initWithFrame:frame])) {
        CAGradientLayer *g = (CAGradientLayer *)self.layer;
        g.colors = @[(id)XSViolet().CGColor, (id)XSPink().CGColor];
        g.startPoint = CGPointMake(0, 0);
        g.endPoint = CGPointMake(1, 1);
        g.cornerRadius = 14;
    }
    return self;
}
@end

@implementation XSPassthroughWindow
- (UIView *)hitTest:(CGPoint)point withEvent:(UIEvent *)event {
    UIView *hit = [super hitTest:point withEvent:event];
    return (hit == self || hit == self.rootViewController.view) ? nil : hit;
}
@end
